using System.Diagnostics;
using System.IO;
using System.Reflection;
using System.Security.Cryptography;
using System.Text.Json;
using CardGame.Core;
using CardGame.Content.Standard;
using CardGame.Wpf.ViewModels;

internal static class Probe
{
    [STAThread]
    private static void Main(string[] args)
    {
        const int count = 11;
        var samples = new List<object>();
        var cold = Stopwatch.StartNew();
        var registry = ComposedSkillContentRegistry.CreateShowcase();
        cold.Stop();
        var validate = typeof(ContentRegistry).GetMethods(BindingFlags.Static | BindingFlags.NonPublic)
            .Single(method => method.Name == "ValidateExpandedProgramCardDomain" &&
                method.GetParameters()[0].ParameterType == typeof(ContentRegistry))
            .CreateDelegate<Action<ContentRegistry>>();
        var options = new GameOptions { Seed = 922, PlayerCount = 4, HumanSeat = 0,
            HumanRole = null, ModeId = "team:standard-2v2", UseInteractiveSetup = true,
            AdvanceAfterHumanCommands = false, UseInteractiveDiscard = false };
        var game = GameEngine.CreateStandard(options, registry);
        var start = game.Submit(new StartGameCommand());
        if (!start.Accepted) throw new InvalidOperationException(start.Error?.Message);
        var checkpoint = game.CreateCheckpoint();
        var expected = Views(game);

        Measure("expanded-validation", () => { validate(registry); return registry; });
        Measure("classic-registry", StandardContentRegistry.CreateWithClassicGeneralsAndTeamModesAndNationalWarAmbitious);
        Measure("showcase-registry", () => ComposedSkillContentRegistry.CreateShowcase());
        Measure("fixed-checkpoint-restore", () => GameReplay.Restore(checkpoint, registry));
        Measure("expanded-table-viewmodel", () => new MainViewModel(autoAdvance: false,
            seed: 922, showSetup: false, useExpandedContent: true));

        var report = new {
            measuredAt = DateTimeOffset.Now, runtime = Environment.Version.ToString(),
            tieredCompilation = Environment.GetEnvironmentVariable("DOTNET_TieredCompilation"),
            warmups = 3, iterations = count, coldShowcaseMs = cold.Elapsed.TotalMilliseconds,
            sourceAssemblyHash = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(ContentRegistry).Assembly.Location))),
            registry.ContentHash, cards = registry.Cards.Count, skills = registry.Skills.Count,
            generals = registry.Generals.Count, checkpointCommands = checkpoint.Commands.Count,
            expectedViews = expected, samples
        };
        File.WriteAllText(args[0], JsonSerializer.Serialize(report, new JsonSerializerOptions { WriteIndented = true }));
        Console.WriteLine(JsonSerializer.Serialize(new { report.coldShowcaseMs, report.sourceAssemblyHash, report.ContentHash }));

        void Measure(string name, Func<object> operation)
        {
            for (var iteration = -3; iteration < count; iteration++)
            {
                GC.Collect(); GC.WaitForPendingFinalizers(); GC.Collect();
                var allocated = GC.GetAllocatedBytesForCurrentThread();
                var watch = Stopwatch.StartNew();
                var result = operation();
                watch.Stop();
                allocated = GC.GetAllocatedBytesForCurrentThread() - allocated;
                if (result is ContentRegistry value && name is not "expanded-validation")
                {
                    if (value.ContentHash != registry.ContentHash && name == "showcase-registry")
                        throw new InvalidOperationException("Showcase fingerprint changed.");
                    if (ReferenceEquals(value.Cards, registry.Cards))
                        throw new InvalidOperationException("Registry isolation was lost.");
                }
                if (result is GameEngine restored && !Views(restored).SequenceEqual(expected))
                    throw new InvalidOperationException("Replay player views changed.");
                if (result is MainViewModel vm)
                {
                    if (vm.Seats.Count != 8) throw new InvalidOperationException("Expanded table seat count changed.");
                    vm.Dispose();
                }
                if (iteration >= 0) samples.Add(new { name, iteration, ms = watch.Elapsed.TotalMilliseconds, allocatedBytes = allocated });
                GC.KeepAlive(result);
            }
        }
    }
    private static string[] Views(GameEngine game) => Enumerable.Range(0, 4)
        .Select(seat => SnapshotJson.Serialize(game.CreateSnapshot(seat))).ToArray();
}
